const raw = [].concat($input.first().json.body ?? []);  // full response: the list is in body
const items = (raw.length === 1 && Array.isArray(raw[0]) ? raw[0] : raw).filter(i => i && i.id && i.status === 'idea');
return items.map(i => ({ json: i }));

const it = $('One per idea').item.json;
const c = $('Campaign').first().json;
const link = $('Campaign link').item.json.url || null;
const exRaw = $('Approved examples').item.json.body;
const examples = (Array.isArray(exRaw) ? exRaw : []).map(e => `- ${e.text}`).join('\n') || null;
const brief = `${it.body}\nCampaign: ${c.name}. Goal: ${c.goal_text}.${c.offer ? ' Offer: ' + c.offer + '.' : ''}`;
// Only what the USER gave counts as evidence for the fact check. The piece's brief was
// written by the planner (an LLM) and once invented "50% off"; as evidence it would have
// approved its own invention.
const userFacts = [`Goal: ${c.goal_text}.`, c.offer ? `Offer: ${c.offer}.` : '', c.audience ? `Audience: ${c.audience}.` : ''].filter(Boolean).join('\n');
let request;
if (it.channel === 'blog') {
  request = { prompt: 'blog_post', vars: { topic: it.title, audience: c.audience || null, context: brief, length_words: 600 } };
} else if (it.channel === 'email') {
  request = { prompt: 'email_newsletter', vars: { topic: it.title, audience: c.audience || null, context: brief } };
} else {
  request = { prompt: 'social_posts', vars: { topic: `${it.title}. ${brief}`, channels: it.channel, link, campaign: c.slug, examples } };
}
return { json: { item_id: it.id, channel: it.channel, link, brief, userFacts, request } };

const b = $('Build request').item.json;
const out = $json.output;
let text;
if (b.channel === 'blog') text = out;
else if (b.channel === 'email') text = `Subject: ${out.subject}\nPreheader: ${out.preheader}\n\n${out.body_markdown}`;
else {
  const post = (out.posts || []).find(p => String(p.channel).trim().toLowerCase() === b.channel) || (out.posts || [])[0];
  if (!post) throw new Error(`No post for ${b.channel}`);
  text = post.text.trim();
  if (b.link && !text.includes(b.link)) text += `\n\n${b.link}`;
}
return { json: { ref: String(b.item_id), channel: b.channel, text, context: b.userFacts, links: b.link || '' } };

// Image-friendly channels get a title card from 17 (17 picks the size from the channel:
// square for instagram/facebook/threads, og for linkedin/x). Other channels, or no
// CARDS_URL, make a harmless GET /health instead so every item still passes through.
const CARD_CHANNELS = ['instagram', 'facebook', 'threads', 'linkedin', 'x'];
function cardRequest(channel, title) {
  const b = ($('Brand profile').first().json || {}).body;
  const brand = b && typeof b === 'object' ? b : {};
  // First line without links, hashtags or emoji (the card font has no emoji glyphs), cut to
  // its first sentence when that is long enough to stand alone.
  const first = String(title || '').split('\n')
    .map(l => l.replace(/https?:\/\/\S+/g, '').replace(/(^|\s)#[\p{L}\p{N}_]+/gu, '$1')
      .replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}\u{20E3}]/gu, '').replace(/\s+/g, ' ').trim())
    .find(l => /[\p{L}\p{N}]/u.test(l)) || '';
  const sentence = (first.match(/^.*?[.!?](?=\s|$)/) || [first])[0];
  const line = sentence.length >= 20 ? sentence : first;
  const t = line.length > 140 ? line.slice(0, 139).replace(/\s+\S*$/, '') + '…' : line;
  if (!$env.CARDS_URL || !CARD_CHANNELS.includes(channel) || !t) {
    return { skip: true, method: 'GET', url: `${$env.CARDS_URL || $env.CALENDAR_URL}/health`, body: '{}' };
  }
  const accent = /^#[0-9a-fA-F]{6}$/.test(String(brand.accent_color || '')) ? brand.accent_color : null;
  return { skip: false, method: 'POST', url: `${$env.CARDS_URL}/cards`, body: JSON.stringify({
    title: t, brand: brand.name ? String(brand.name).slice(0, 40) : null, channel, accent }) };
}

const idea = $('One per idea').all().map(i => i.json).find(i => String(i.id) === String($json.ref)) || {};
return { json: { ...cardRequest($json.channel, idea.title || $json.text), post: $json } };

function imageUrlOf(req, res) {
  return !req.skip && res && res.statusCode === 201 && res.body && typeof res.body.url === 'string' ? res.body.url : null;
}
const NO_IMAGE_IG = 'No image: the title card (17-image-cards) could not be made, and Instagram cannot be published without one. Add an image_url before approving.';

const req = $('Card request').item.json;
const g = req.post;
const image_url = imageUrlOf(req, $json);
return { json: { ...g, image_url, image_note: !image_url && g.channel === 'instagram' ? NO_IMAGE_IG : null } };

function rawOps(ops) { return ops.length ? ops.map(o => ({ json: o })) : [{ json: { stage: 0 } }]; }

const base = $env.CALENDAR_URL;
const ops = [];
for (const r of $input.all().map(i => i.json)) {
  const id = r.ref;
  const patch = { body: r.text };
  if (r.image_url) patch.image_url = r.image_url;
  ops.push({ stage: 1, method: 'PATCH', url: `${base}/items/${id}`, body: patch });
  const note = r.ok ? 'drafted by campaign drafter' : `drafted; needs a human. Quality gate: ${r.problems.join('; ')}`;
  ops.push({ stage: 2, method: 'POST', url: `${base}/items/${id}/status`, body: { status: 'draft',
    note: r.image_note ? `${note}. ${r.image_note}` : note } });
  if (r.ok) ops.push({ stage: 3, method: 'POST', url: `${base}/items/${id}/status`, body: { status: 'in_review', note: 'passed the quality gate' } });
}
return rawOps(ops);

function opsToItems(ops, base) {
  if (!ops.length) return [{ json: { method: 'GET', url: `${base}/health`, body: '{}', noop: true } }];
  return ops.map(o => ({ json: { ...o, body: JSON.stringify(o.body || {}) } }));
}

const ops = $('Save ops').all().map(i => i.json).filter(o => o.stage === 1);
return opsToItems(ops, $env.CALENDAR_URL);

function opsToItems(ops, base) {
  if (!ops.length) return [{ json: { method: 'GET', url: `${base}/health`, body: '{}', noop: true } }];
  return ops.map(o => ({ json: { ...o, body: JSON.stringify(o.body || {}) } }));
}

const ops = $('Save ops').all().map(i => i.json).filter(o => o.stage === 2);
return opsToItems(ops, $env.CALENDAR_URL);

function opsToItems(ops, base) {
  if (!ops.length) return [{ json: { method: 'GET', url: `${base}/health`, body: '{}', noop: true } }];
  return ops.map(o => ({ json: { ...o, body: JSON.stringify(o.body || {}) } }));
}

const ops = $('Save ops').all().map(i => i.json).filter(o => o.stage === 3);
return opsToItems(ops, $env.CALENDAR_URL);

function failedOps(runNodes) {
  return runNodes.flatMap(n => $(n).all()).filter(r => !r.json.noop && r.json.statusCode >= 300)
    .map(r => JSON.stringify((r.json.body || {}).detail || r.json.body));
}

const results = $('Quality gate').all().map(i => i.json);
const failed = failedOps(['Run stage 1', 'Run stage 2', 'Run stage 3']);
const c = $('Campaign').first().json;
const ok = results.filter(r => r.ok).length;
return [{ json: { ready: ok, text: `*Campaign "${c.name}"*: ${ok} of ${results.length} drafts ready in the approval form` +
  (results.length - ok ? `, ${results.length - ok} saved as drafts that need a human` : '') +
  (failed.length ? ` (${failed.length} calendar updates failed: ${failed.slice(0, 3).join('; ')})` : '') } }];

function notifyRequest(text, env, waits) {
  const fmt = String(env.NOTIFY_FORMAT || 'generic').trim().toLowerCase();
  const telegram = fmt === 'telegram';
  if (telegram ? !(env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID) : !env.NOTIFY_WEBHOOK_URL) return null;
  const plain = String(text ?? '');
  const form = `${String(env.N8N_PUBLIC_URL || 'http://localhost:5678/').trim().replace(/\/?$/, '/')}form/mkt-content-approval`;
  const link = waits && !plain.includes(form) ? form : null;   // already in the text: once is enough
  // Cut the text (never the link) to the longest prefix whose rendered message fits:
  // escaping can make the rendered text several times longer, so search for it.
  const fit = (render, max) => {
    if (render(plain).length <= max) return render(plain);
    let lo = 0, hi = plain.length;
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2);
      if (render(plain.slice(0, mid).trimEnd() + '…').length <= max) lo = mid; else hi = mid - 1;
    }
    return render(plain.slice(0, lo).trimEnd() + '…');
  };
  const mdLink = /\[([^\]\n]+)\]\((https?:\/\/[^\s)"<>]+)\)/g;
  const oneStar = /(^|[^*\w])\*(?![\s*])([^*\n]*?[^\s*])\*(?![*\w])/g;   // Slack-style *bold*
  const heading = /^#{1,6}[ \t]+(.+)$/gm;
  if (telegram) {
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const render = t => esc(t)
      .replace(mdLink, '<a href="$2">$1</a>')
      .replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>').replace(oneStar, '$1<b>$2</b>').replace(heading, '<b>$1</b>')
      + (link ? `\n\n<a href="${esc(link)}">Open the approval form</a>` : '');
    const api = String(env.TELEGRAM_API_URL || 'https://api.telegram.org').trim().replace(/\/+$/, '');
    return { format: 'telegram', url: `${api}/bot<TELEGRAM_BOT_TOKEN>/sendMessage`, body: {
      chat_id: String(env.TELEGRAM_CHAT_ID).trim(), text: fit(render, 4096), parse_mode: 'HTML',
      disable_web_page_preview: true } };
  }
  const url = '<NOTIFY_WEBHOOK_URL>';
  if (fmt === 'slack') {
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const render = t => esc(t)
      .replace(mdLink, '<$2|$1>').replace(/\*\*([^*\n]+)\*\*/g, '*$1*').replace(heading, '*$1*')
      + (link ? `\n\n<${link}|Open the approval form>` : '');
    return { format: 'slack', url, body: { text: fit(render, 40000) } };
  }
  if (fmt === 'discord') {
    // <url> stops link previews; Discord bold is **x**; nothing in the text can ping anyone.
    const render = t => t.replace(oneStar, '$1**$2**').replace(/(^|\s)(https?:\/\/[^\s<>]+)/g, '$1<$2>')
      + (link ? `\n\nApproval form: <${link}>` : '');
    return { format: 'discord', url, body: { content: fit(render, 2000), allowed_mentions: { parse: [] } } };
  }
  const t = link ? `${plain.trimEnd()}\n\nApproval form: ${link}` : plain;
  return { format: 'generic', url, body: { text: t, content: t } };   // the payload before NOTIFY_FORMAT
}

return $input.all().flatMap(item => {
  const req = notifyRequest(item.json.text, $env, item.json.ready > 0);
  return req ? [{ json: req }] : [];
});
